def _logo_bytes()   -> io.BytesIO: return io.BytesIO(base64.b64decode(_KAFA_LOGO_B64))
def _ribbon_bytes() -> io.BytesIO: return io.BytesIO(base64.b64decode(_GOLDEN_RIBBON_B64))
def _oswald_sig_bytes()  -> io.BytesIO: return io.BytesIO(base64.b64decode(_OSWALD_SIG_B64))
def _verlene_sig_bytes() -> io.BytesIO: return io.BytesIO(base64.b64decode(_VERLENE_SIG_B64))


def _fetch_logo(s3_client, s3_path: str) -> io.BytesIO:
    if s3_path and s3_path.startswith("s3://"):
        try:
            bucket, _, key = s3_path[len("s3://"):].partition("/")
            resp = s3_client.get_object(Bucket=bucket, Key=key)
            return io.BytesIO(resp["Body"].read())
        except Exception:
            pass
    return _logo_bytes()


def _ensure_mk_format(member_id: str) -> str:
    if not member_id or member_id.startswith("___"):
        return member_id
    return member_id


def generate_pdf(member: dict, company: dict, certificate_id: str,
                 issued_date: str, s3_client=None) -> bytes:
    from reportlab.platypus import Image as RLImage

    buf = io.BytesIO()
    doc = SimpleDocTemplate(
        buf, pagesize=landscape(LETTER),
        leftMargin=2.5*cm, rightMargin=2.5*cm,
        topMargin=2.0*cm,  bottomMargin=2.0*cm,
    )

    GREEN = colors.HexColor("#1a5c1a")
    GOLD  = colors.HexColor("#d4a017")
    DARK  = colors.HexColor("#1a1a1a")
    GREY  = colors.HexColor("#555555")

    def _page_border(canvas, _doc):
        w, h = landscape(LETTER)
        m = 18
        canvas.saveState()
        canvas.setStrokeColor(GREEN)
        canvas.setLineWidth(4)
        canvas.rect(m, m, w - 2*m, h - 2*m)
        canvas.setStrokeColor(GOLD)
        canvas.setLineWidth(2)
        inner = m + 10
        canvas.rect(inner, inner, w - 2*inner, h - 2*inner)
        canvas.restoreState()

    def S(name, **kw):
        base = dict(fontName="Helvetica", textColor=DARK, leading=16)
        base.update(kw)
        return ParagraphStyle(name, **base)

    s = {
        "addr":    S("addr",    fontSize=9,  textColor=GREY, alignment=TA_RIGHT, leading=14),
        "title":   S("title",   fontSize=26, fontName="Helvetica-Bold", alignment=TA_CENTER, spaceAfter=22),
        "intro":   S("intro",   fontSize=11, alignment=TA_JUSTIFY, spaceAfter=10, leading=16),
        "name":    S("name",    fontSize=26, fontName="Times-BoldItalic", alignment=TA_CENTER, spaceAfter=20),
        "body":    S("body",    fontSize=11, alignment=TA_JUSTIFY, spaceAfter=6,  leading=16),
        "date":    S("date",    fontSize=11, alignment=TA_JUSTIFY, spaceAfter=10, leading=16),
        "signame": S("signame", fontSize=10, fontName="Helvetica-Bold", alignment=TA_CENTER,
                     spaceBefore=2, spaceAfter=0),
        "sigtit":  S("sigtit",  fontSize=9,  textColor=GREY, alignment=TA_CENTER,
                     spaceBefore=0, spaceAfter=0),
        "footer":  S("footer",  fontSize=8,  textColor=GREY, alignment=TA_LEFT),
        "footerid":S("footerid",fontSize=8,  textColor=GREY, alignment=TA_RIGHT),
    }

    co_name  = company.get("name",         "Koperativ Asirans Fòs Ayiti (KAFA)")
    co_reg   = company.get("registration_number", "")
    co_id    = company.get("companyId", company.get("company_id", ""))
    if not co_reg or co_reg == co_id:
        co_reg = "E-10-ASS/03-2026-050"
    co_logo  = company.get("path_to_logo", "")
    co_siege = company.get("siege_social", "Léogâne, Haïti")
    co_phone = company.get("phone",        "")
    sec_name  = company.get("secretary_name",  "Verlène D. Rebecca")
    sec_title = company.get("secretary_title", "Secrétaire CA")
    dir_name  = company.get("director_name",   "Oswald Mathieu")
    dir_title = company.get("director_title",  "Président CA")

    m_name = member.get("full_name", "___________________________")
    m_num  = _ensure_mk_format(member.get("memberId", ""))

    join_raw = member.get("join_date", "") or member.get("created_at", "")
    try:
        join_year = datetime.strptime(str(join_raw)[:10], "%Y-%m-%d").year
    except (ValueError, TypeError):
        join_year = datetime.now().year

    sex   = member.get("sex", "")
    admis = "admise" if sex == "Female" else "admis"

    story = []

    logo_data = _fetch_logo(s3_client, co_logo) if s3_client else _logo_bytes()
    addr_parts = [f"Siège Social : {co_siege}"] if co_siege else []
    if co_phone:
        addr_parts.append(f"Tél : {co_phone}")
    addr_html = "<br/>".join(addr_parts)

    logo_img = RLImage(logo_data, width=3.5*cm, height=2.8*cm)
    header = Table([[logo_img, Paragraph(addr_html, s["addr"])]], colWidths=["30%", "70%"])
    header.setStyle(TableStyle([
        ("VALIGN",      (0,0), (-1,-1), "MIDDLE"),
        ("LEFTPADDING", (0,0), (-1,-1), 0),
        ("RIGHTPADDING",(0,0), (-1,-1), 0),
    ]))
    story.append(header)
    story.append(Spacer(1, 0.3*cm))
    story.append(Paragraph("CERTIFICAT OFFICIEL D'ADHÉSION", s["title"]))
    story.append(Paragraph(
        f"La <b>{co_name}</b>, constituée conformément aux lois de la République d'Haïti "
        f"et régulièrement enregistrée au numéro <b>{co_reg}</b> certifie que :",
        s["intro"],
    ))
    story.append(Paragraph(m_name, s["name"]))
    story.append(Spacer(1, 0.2*cm))
    story.append(Paragraph(
        f"est {admis} comme membre de la KAFA depuis <b>{join_year}</b> et bénéficie "
        "des droits, privilèges et garanties prévus par les statuts de la coopérative "
        "ainsi que par les programmes offerts aux membres conformément aux règlements "
        "internes en vigueur.",
        s["body"],
    ))
    story.append(Paragraph(
        f"« Le présent certificat lui est délivré pour servir et valoir ce que "
        f"de droit, le {issued_date} »",
        s["date"],
    ))
    story.append(Spacer(1, 0.4*cm))

    # ── Signature block ───────────────────────────────────────────────────────
    # Signature images rendered at 5.5cm wide, aspect-correct
    verlene_img = RLImage(_verlene_sig_bytes(), width=5.5*cm, height=5.5*(57/260)*cm)
    oswald_img  = RLImage(_oswald_sig_bytes(),  width=5.5*cm, height=5.5*(33/307)*cm)
    ribbon_img  = RLImage(_ribbon_bytes(),       width=2.8*cm, height=3.42*cm)

    # Each signature col: image sits BOTTOM-aligned directly above the line,
    # then name and title with tight padding.
    def sig_col(img, name, title):
        col = Table(
            [
                [img],
                [HRFlowable(width="100%", thickness=1, color=DARK)],
                [Paragraph(f"<b>{name}</b>", s["signame"])],
                [Paragraph(title, s["sigtit"])],
            ],
            colWidths=["100%"],
        )
        col.setStyle(TableStyle([
            ("ALIGN",         (0,0), (-1,-1), "CENTER"),
            ("VALIGN",        (0,0), (0,0),   "BOTTOM"),   # image sticks to line
            ("LEFTPADDING",   (0,0), (-1,-1), 0),
            ("RIGHTPADDING",  (0,0), (-1,-1), 0),
            ("TOPPADDING",    (0,0), (-1,-1), 0),
            ("BOTTOMPADDING", (0,0), (-1,-1), 2),
            ("BOTTOMPADDING", (0,0), (0,0),   0),          # no gap between image and line
            ("TOPPADDING",    (0,1), (0,1),   0),          # no gap above line
        ]))
        return col

    seal_cell = Table([[ribbon_img]], colWidths=["100%"])
    seal_cell.setStyle(TableStyle([
        ("ALIGN",  (0,0), (-1,-1), "CENTER"),
        ("VALIGN", (0,0), (-1,-1), "MIDDLE"),
    ]))

    sig_table = Table(
        [[sig_col(verlene_img, sec_name, sec_title),
          seal_cell,
          sig_col(oswald_img,  dir_name, dir_title)]],
        colWidths=["38%", "24%", "38%"],
    )
    sig_table.setStyle(TableStyle([
        ("VALIGN",        (0,0), (-1,-1), "BOTTOM"),
        ("LEFTPADDING",   (0,0), (-1,-1), 0),
        ("RIGHTPADDING",  (0,0), (-1,-1), 0),
        ("TOPPADDING",    (0,0), (-1,-1), 0),
        ("BOTTOMPADDING", (0,0), (-1,-1), 0),
    ]))

    footer_table = Table(
        [[Paragraph(f"No membre : {m_num}", s["footer"]),
          Paragraph(f"Certificat ID : {certificate_id}", s["footerid"])]],
        colWidths=["50%", "50%"],
    )
    footer_table.setStyle(TableStyle([
        ("LEFTPADDING",  (0,0), (-1,-1), 0),
        ("RIGHTPADDING", (0,0), (-1,-1), 0),
    ]))

    story.append(KeepTogether([
        sig_table,
        Spacer(1, 0.3*cm),
        footer_table,
    ]))

    doc.build(story, onFirstPage=_page_border, onLaterPages=_page_border)
    return buf.getvalue()


def generate_jpeg(pdf_bytes: bytes) -> bytes:
    import fitz  # PyMuPDF — no poppler dependency
    doc  = fitz.open(stream=pdf_bytes, filetype="pdf")
    page = doc[0]
    mat  = fitz.Matrix(150 / 72, 150 / 72)  # 150 dpi
    pix  = page.get_pixmap(matrix=mat, alpha=False)
    buf  = io.BytesIO()
    buf.write(pix.tobytes("jpeg"))
    return buf.getvalue()
